import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"63、【既济】 离下坎上","description":"周易口诀义 - 63、【既济】 离下坎上","frontmatter":{"title":"63、【既济】 离下坎上","description":"周易口诀义 - 63、【既济】 离下坎上"},"headers":[],"relativePath":"zh/classics/koujueyi/065.md","filePath":"zh/classics/koujueyi/065.md"}'),r={name:"zh/classics/koujueyi/065.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_63、【既济】-离下坎上" tabindex="-1">63、【既济】 离下坎上 <a class="header-anchor" href="#_63、【既济】-离下坎上" aria-label="Permalink to “63、【既济】 离下坎上”">​</a></h1><p>彖曰：「既济亨小」者，亨也。「利贞」，刚柔正而位当也。「初吉」，柔得中也。终止则乱，其道穷也。</p><p>象曰：水在火上，既济，君子以思患而豫防之。</p><p>初九：曳其轮，濡其尾，无咎。</p><p>象曰：「曳其轮」，义无咎也。</p><p>六二：妇丧其茀，勿逐，七日得。</p><p>象曰：「七日得」，以中道也。</p><p>九三：高宗伐鬼方，三年克之，小人勿用。</p><p>象曰：「三年克之」，惫也。</p><p>六四，𦈡有衣袽，终日戒。</p><p>象曰：「终日戒」，有所疑也。</p><p>九五，东邻杀牛，不如西邻之礿祭，实受其福。</p><p>象曰：「东邻杀牛」，不如西邻之时也；「实受其福」，吉大来也。</p><p>上六，濡其首，厉。</p><p>象曰：「濡其首厉」，何可久也！</p><p>解读</p><p>「既济，亨小利贞」者，既，尽也；济，渡也；刚柔得正，上下相应，故曰「既济」也。万物尽皆济渡，若小者不通，则无尽济之理。今小者犹尚通亨，则柔大之物自然获济，故曰「亨小」也。物既尽济，非正不可，故曰「利贞」。「初吉终乱」者，此设戒之辞。当既济之时，若能戒慎谦守，不为骄恣，则既济无穷，安有危乱及己！若其不能居安虑危，慎终如始，则既济其极，危乱至矣。故王传云「终乱不如自乱，由止故乱」是也。</p><p>象曰「水在火上，既济」者，孔义云：「水在火上，炊爨之象，饮食以之而成，性命以之而济，是故既济象也。」「君子以思患豫防之」者，处既济之时，举事合宜，恣情所欲，固当恭俭保守，存不忘亡，思虑后患，豫为防慎，故书云「制治于未乱，保邦于未危」是也。</p><p>「初九，曳其轮，濡其尾，无咎」者，初九处既济之初，是始济渡也。始济险难，未至乾燥之地，犹拖曳其轮，濡湿其尾，言其劳苦，方始获济，其于义理，安有咎哉？故曰「无咎」也。</p><p>「六二，妇丧其茀，勿逐，七日得」者，茀者，妇人之首饰也。六二居中履正，而应于五，虽与初三相近，情不相得，遂被初三相夺。以人事明之，其犹贞洁之妇，容仪光丽，夫暂不在，遂被他人侵陵，头上花饰，强为窃夺，故曰「妇丧其茀」。称「妇」者，明己自有夫而被见侵。当既济之时，法令明峻，不容邪道，妇既执贞如此，众尚节志，皆愿助之，假使逃窜，势不能久，不过七日，必见执获，故曰「勿逐，七日得」也。</p><p>「九三，高宗伐鬼方，三年克之，小人勿用」者，处既济之时，居文明之末，将入险难，是居衰而能济。其犹殷王高宗谅阴三年，盛德中兴，克伐鬼方，以其盛德始兴，不能即胜，故三年已后，乃始克胜，故曰「三年克之」也。高宗者，武丁之号，殷之贤王，挺济衰世，能伐远方。若小人居之，必致危乱，不可任用，故曰「小人勿用」也。</p><p>「六四，𦈡有衣袽，终日戒」者，𦈡宜曰濡，是沾湿之义；袽者，衣敝烂者，可以塞漏舟也。六四处得其位，而与三五相近，情不相得，常虑危患及身，如舟之穿漏而能得济渡者，必须敝烂之衣塞之，免为濡溺，方遂获济，故曰「濡有衣袽」也。邻不亲而得全者，须防戒得免，故曰「终日戒」也。</p><p>「九五，东邻杀牛，不如西邻之礿祭，实受其福」者，牛，祭之盛也。礿是殷时春祭之名，四时最薄之祭也。九五处既济之时，得居尊位，天下尽皆获济，亦何所营为？喻天下太平，不劳思虑，其所务者，莫过祭祀，祭祀之本，莫过修德。今九五履正居中，修德如此，但可礿祭省薄，精诚致敬，合时之宜，则神明降福。假使东邻杀牛，丰厚之盛，神灵不飨，不如西邻薄祭，吉福大来。此苹蘩可荐之义，故惟德是馨矣。</p><p>上六：濡其首，厉者，处既济之极，物极则反，遂至于未济者，则首先犯焉。若既济之时，守谦保位，无为无事，安能有咎？今既进而不已，遂遇危难，故濡其首也。既被濡者，将陷于难，危莫甚焉，故曰「濡其首厉」也。</p>',24)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
